{
  "name": "bench-agents",
  "private": true,
  "type": "module",
  "scripts": { "dev": "wrangler dev", "deploy": "wrangler deploy" },
  "dependencies": { "agents": "0.27.0", "ai": "^7.0.0", "workers-ai-provider": "^4.0.0" },
  "devDependencies": { "wrangler": "4.148.0" }
}
{
  "name": "bench-agent",
  "main": "src/index.js",
  "compatibility_date": "2026-10-01",
  "ai": { "binding": "AI" },
  "durable_objects": { "bindings": [{ "name": "Chat", "class_name": "Chat" }] },
  "migrations": [{ "tag": "v1", "new_sqlite_classes": ["Chat"] }]
}
import { generateText } from 'ai';
import { createWorkersAI } from 'workers-ai-provider';

export async function summarize(env, text) {
  const workersai = createWorkersAI({ binding: env.AI });
  const { text: summary } = await generateText({
    model: workersai('@cf/meta/llama-3.3-70b-instruct-fp8-fast'),
    system: 'Summarize the text in three sentences.',
    prompt: text,
  });
  return summary;
}
